export const seedCategories: SeedCategory[] = rawCategories.map((c, i) => ({
  id: i + 1,
  name: c.name,
  slug: c.slug,
  description: c.description,
  productCount: rawProducts.filter((p) => p.categorySlug === c.slug).length,
  iconName: c.iconName,
}));

export const seedProducts: SeedProduct[] = rawProducts.map((p, i) => ({
  id: i + 1,
  name: p.name,
  description: p.description,
  price: parseFloat(String(p.price)),
  originalPrice: p.originalPrice ? parseFloat(String(p.originalPrice)) : undefined,
  category: p.category,
  categorySlug: p.categorySlug,
  brand: p.brand,
  imageUrl: p.imageUrl,
  rating: parseFloat(String(p.rating)),
  reviewCount: p.reviewCount,
  inStock: p.inStock,
  tags: [...p.tags],
  featured: p.featured,
}));
